(() => {
  const {e,icon,serviceCard}=window.UI;
  const {t,content}=window.I18N;
  function aboutSection(standalone=false){
    const config=content(),a=config.about,tag=standalone?'h1':'h2';
    return '<section class="about-section section '+(standalone?'standalone-about':'')+'" id="about"><div class="container"><div class="about-layout"><div class="about-copy"><span class="eyebrow">'+e(a.eyebrow)+'</span><'+tag+'>'+e(a.title)+'<br><span class="muted">'+e(a.accent)+'</span></'+tag+'><p>'+e(a.description)+'</p>'+(standalone?'<p>'+e(a.approach)+'</p>':'<a class="text-link" href="#/about">'+t('aboutLink')+' '+icon('arrow')+'</a>')+'</div><div class="about-brand-card"><span class="brand-logo-frame about-logo-frame"><img class="brand-logo" src="'+e(config.company.logoFull)+'" alt="'+e(config.company.name)+'" width="1254" height="1254"></span><p>'+e(a.caption)+'</p></div></div><div class="about-values">'+a.values.map(v=>'<article><span>'+icon(v.icon)+'</span><div><h3>'+e(v.title)+'</h3><p>'+e(v.description)+'</p></div></article>').join('')+'</div></div></section>';
  }
  function home(){
    const config=content();
    return '<main id="main" class="home-page">'+window.Studio.hero()+'<section class="services-section section" id="services"><div class="container"><div class="section-heading"><div><span class="eyebrow"><span class="section-number">01</span>'+t('services')+'</span><h2>'+t('studioServicesTitle')+' <span class="muted">'+t('studioServicesAccent')+'</span></h2></div><p>'+t('studioServicesIntro')+'</p></div><div class="services-grid">'+config.services.map(serviceCard).join('')+'</div></div></section><section class="activities-section section" id="activities"><div class="container"><div class="section-heading"><div><span class="eyebrow"><span class="section-number">02</span>'+t('byBusiness')+'</span><h2>'+t('activityTitle')+'</h2></div><p>'+t('activityIntro')+'</p></div><div class="activity-panel"><div class="activity-tabs" role="tablist" aria-label="'+e(t('chooseActivity'))+'">'+config.activities.map((a,i)=>'<button role="tab" id="tab-'+a.id+'" aria-controls="activity-result" aria-selected="'+(i===0)+'" tabindex="'+(i===0?0:-1)+'" class="activity-tab '+(i===0?'selected':'')+'" data-activity="'+a.id+'">'+icon(a.icon)+'<span>'+e(a.title)+'</span><span class="tab-arrow">'+icon('arrow')+'</span></button>').join('')+'</div><div id="activity-result" class="activity-result" role="tabpanel" aria-labelledby="tab-shop"></div></div></div></section>'+window.Experiences.section()+aboutSection()+window.Studio.process()+window.Experiences.faq()+window.Views.contactSection()+'</main>';
  }
  function aboutPage(){return '<main id="main" class="about-page"><div class="container"><div class="breadcrumb"><a href="#/">'+t('home')+'</a>'+icon('chevron')+'<span>'+t('about')+'</span></div></div>'+aboutSection(true)+'<section class="experience-cta"><div class="container"><div><h2>'+t('serviceCtaTitle')+'</h2><p>'+t('serviceCtaDesc')+'</p></div><a href="#/contact" class="button button-orange">'+t('discuss')+icon('arrow')+'</a></div></section></main>';}
  Object.assign(window.Views,{home,aboutPage});
})();
